INSERT INTO public.tools_catalog (id, name, description, category, tool_types, source, is_live, is_premium, is_free, dedicated_route, display_order, extra_categories)
VALUES
  ('meal-plan-studio', 'Meal Plan Studio', 'A 4-week Indian meal plan for your goal, diet and budget: daily menus, portions, grocery lists, prep plan and swaps you will enjoy.', 'Health & Wellness', ARRAY['Nutrition', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Home, Family & Travel']),
  ('fitness-programme-builder', 'Fitness Programme Builder', 'A 12-week workout programme for home or gym, matched to your goal, level and time, with progressions, form cues and a tracker.', 'Health & Wellness', ARRAY['Fitness', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('lab-report-explainer', 'Lab Report Explainer', 'Upload blood test or health check-up reports to understand each value in plain words, what is out of range and what to ask your doctor.', 'Health & Wellness', ARRAY['Medical Reports', 'Health'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('diabetes-lifestyle-coach', 'Diabetes Lifestyle Coach', 'A supportive coach for living well with diabetes: Indian meals, sugar log patterns, walks, sleep and stress, alongside your doctor''s plan.', 'Health & Wellness', ARRAY['Diabetes', 'Coaching'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('pregnancy-journey-planner', 'Pregnancy Journey Planner', 'A week-by-week pregnancy companion: doctor visits and tests to ask about, food, exercise, hospital bag, money and baby prep checklists.', 'Health & Wellness', ARRAY['Pregnancy', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Home, Family & Travel']),
  ('wellness-journal-coach', 'Wellness Journal Coach', 'A gentle guided journalling session for stress, sleep and mood, ending with reflections, a calm routine and small next steps.', 'Health & Wellness', ARRAY['Mental Wellbeing', 'Coaching'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('home-interior-designer', 'Home Interior Designer', 'Upload a photo of your room and see it redesigned in styles like modern Indian, minimal, boho or luxury, keeping your room''s layout.', 'Home, Family & Travel', ARRAY['Interior Design', 'AI Image'], 'featured', true, false, false, NULL, 0, ARRAY['AI Image Generation']),
  ('renovation-planner', 'Renovation Planner', 'Plan a home renovation: scope, budget with contingency, sequence of work, contractor questions, material choices and a timeline.', 'Home, Family & Travel', ARRAY['Home Improvement', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('balcony-and-garden-planner', 'Balcony and Garden Planner', 'Photograph your balcony or terrace to get a plant plan for its sunlight: plant list, layout, pots, care calendar and a design image.', 'Home, Family & Travel', ARRAY['Gardening', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('trip-planner-studio', 'Trip Planner Studio', 'Plan a complete trip: day-by-day itinerary, routes, stays by area, budget, bookings checklist, packing list and local food to try.', 'Home, Family & Travel', ARRAY['Travel', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('pilgrimage-planner', 'Pilgrimage Planner', 'Plan a yatra or pilgrimage for family and elders: route, darshan planning, registrations to check, health prep, stays and packing.', 'Home, Family & Travel', ARRAY['Travel', 'Spiritual'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('visa-application-kit', 'Visa Application Kit', 'Prepare a visa application: document checklist, cover letter, travel itinerary, financial summary and interview practice questions.', 'Home, Family & Travel', ARRAY['Visa', 'Travel'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('house-moving-planner', 'House Moving Planner', 'Plan a house move or city shift: 6-week timeline, packers checklist, address changes, utilities, school transfers and first-week setup.', 'Home, Family & Travel', ARRAY['Moving', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('car-buying-advisor', 'Car Buying Advisor', 'Choose the right car for your needs and budget: total cost of ownership, new vs used, fuel type, test-drive checklist and negotiation tips.', 'Home, Family & Travel', ARRAY['Cars', 'Planning'], 'featured', true, false, false, NULL, 0, ARRAY['Money & Planning']),
  ('wardrobe-stylist', 'Wardrobe Stylist', 'Upload photos of your clothes to get outfit combinations, your colour palette, gaps to fill and a capsule wardrobe for work and occasions.', 'Home, Family & Travel', ARRAY['Fashion', 'Styling'], 'featured', true, false, false, NULL, 0, ARRAY['Personal']),
  ('skin-and-hair-routine-builder', 'Skin and Hair Routine Builder', 'Share a photo and your concerns to get a simple morning and night skin and hair routine by ingredient type, with a budget option.', 'Health & Wellness', ARRAY['Skincare', 'Routine'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('pet-care-planner', 'Pet Care Planner', 'A complete care plan for your dog or cat: food, vaccinations and vet visits to discuss, grooming, training, budget and an emergency plan.', 'Home, Family & Travel', ARRAY['Pets', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('home-maintenance-manager', 'Home Maintenance Manager', 'A year-round home maintenance plan: monthly and seasonal tasks, appliance service schedule, monsoon prep, budget and records.', 'Home, Family & Travel', ARRAY['Home Care', 'Planning'], 'featured', true, false, false, NULL, 0, '{}'::text[]),
  ('housing-society-kit', 'Housing Society Kit', 'For RWA and society committees: meeting agendas, minutes, notices, maintenance policy, budget, vendor rules and resident messages.', 'Home, Family & Travel', ARRAY['Housing Society', 'Documents'], 'featured', true, false, false, NULL, 0, ARRAY['Legal & Compliance']),
  ('parent-health-tracker', 'Parent Health Tracker', 'Upload your parents'' prescriptions and reports to get a medicine schedule, doctor visit plan, test reminders and a one-page health summary.', 'Health & Wellness', ARRAY['Elder Care', 'Health'], 'featured', true, false, false, NULL, 0, ARRAY['Home, Family & Travel'])
